#include <algorithm>
#include <map>
#include <optional>
#include <set>
#include <string>
#include <vector>

using Holders = std::map<std::string, std::string>;
using Waits = std::map<std::string, std::string>;

std::optional<std::vector<std::string>> findDeadlock(const Holders& holders, const Waits& waits)
{
    const auto next = [&](const std::string& p) -> std::optional<std::string> {
        const auto w{ waits.find(p) };
        if (w == waits.end()) return std::nullopt;
        const auto h{ holders.find(w->second) };
        if (h == holders.end()) return std::nullopt;
        return h->second;
    };
    for (const auto& [start, lock] : waits)
    {
        std::vector<std::string> path;
        std::set<std::string> seen;
        std::optional<std::string> at{ start };
        while (at && !seen.count(*at))
        {
            seen.insert(*at);
            path.push_back(*at);
            at = next(*at);
        }
        if (!at) continue;
        const auto loopStart{ std::find(path.begin(), path.end(), *at) };
        std::vector<std::string> cycle(loopStart, path.end());
        std::rotate(cycle.begin(), std::min_element(cycle.begin(), cycle.end()), cycle.end());
        return cycle;
    }
    return std::nullopt;
}

std::optional<std::string> orderViolation(const std::vector<std::string>& locksTaken, const std::map<std::string, int>& rank)
{
    std::optional<int> highest;
    for (const std::string& lock : locksTaken)
    {
        const auto r{ rank.find(lock) };
        if (r == rank.end()) continue;
        if (highest && *highest >= r->second) return lock;
        highest = highest ? std::max(*highest, r->second) : r->second;
    }
    return std::nullopt;
}

