using S = std::vector<std::string>;
TEST("the classic two-process deadlock") {
    const Holders holders{ { "settings", "A" }, { "cache", "B" } };
    const Waits waits{ { "A", "cache" }, { "B", "settings" } };
    const auto cycle{ findDeadlock(holders, waits) };
    CHECK(cycle.has_value());
    if (cycle) CHECK_EQ(*cycle, (S{ "A", "B" }));
}
TEST("a longer cycle, reported from the smallest name") {
    const Holders holders{ { "l1", "zed" }, { "l2", "mia" }, { "l3", "kai" } };
    const Waits waits{ { "mia", "l1" }, { "zed", "l3" }, { "kai", "l2" }, { "bob", "l2" } };
    const auto cycle{ findDeadlock(holders, waits) };
    CHECK(cycle.has_value());
    if (cycle) CHECK_EQ(*cycle, (S{ "kai", "mia", "zed" }));
}
TEST("waiting is not always deadlock") {
    CHECK(!findDeadlock({ { "lock", "A" } }, { { "B", "lock" } }).has_value());
    CHECK(!findDeadlock({}, { { "B", "free-lock" } }).has_value());
    CHECK(!findDeadlock({ { "x", "A" }, { "y", "B" } }, { { "A", "y" } }).has_value());
    CHECK(!findDeadlock({}, {}).has_value());
}
TEST("lock order") {
    const std::map<std::string, int> rank{ { "settings", 1 }, { "cache", 2 }, { "log", 3 } };
    CHECK(!orderViolation({ "settings", "cache", "log" }, rank).has_value());
    CHECK(!orderViolation({ "settings", "log" }, rank).has_value());
    CHECK_EQ(orderViolation({ "cache", "settings" }, rank).value_or("?"), std::string("settings"));
    CHECK_EQ(orderViolation({ "log", "temp", "cache" }, rank).value_or("?"), std::string("cache"));
    CHECK_EQ(orderViolation({ "cache", "cache" }, rank).value_or("?"), std::string("cache"));
}

